19	pub(crate) fn parse_theme_at_rule(p: &mut CssParser) -> ParsedSyntax {
20	    if !p.at(T![theme]) {
21	        return Absent;
22	    }
23	
24	    let m = p.start();
25	
26	    p.bump(T![theme]);
27	    parse_regular_identifier(p).ok();
28	    parse_declaration_or_rule_list_block(p);
29	
30	    Present(m.complete(p, TW_THEME_AT_RULE))
