34	// @utility tab-* { tab-size: --value([integer]); }
35	pub(crate) fn parse_utility_at_rule(p: &mut CssParser) -> ParsedSyntax {
36	    if !p.at(T![utility]) {
37	        return Absent;
38	    }
39	
40	    let m = p.start();
41	    p.bump(T![utility]);
42	
43	    // Parse utility name - can be simple or functional
44	    if !is_at_utility_identifier(p) {
45	        p.error(expected_identifier(p, p.cur_range()));
46	        return Present(m.complete(p, CSS_BOGUS_AT_RULE));
47	    }
48	
49	    parse_utility_name(p)
50	        .or_recover_with_token_set(
51	            p,
52	            &ParseRecoveryTokenSet::new(CSS_BOGUS_CUSTOM_IDENTIFIER, token_set![T!['{']]),
53	            expected_identifier,
54	        )
55	        .ok();
56	
57	    parse_declaration_or_rule_list_block(p);
58	
59	    Present(m.complete(p, TW_UTILITY_AT_RULE))
