153	fn parse_custom_variant_shorthand(p: &mut CssParser) -> ParsedSyntax {
154	    if !p.at(T!['(']) {
155	        return Absent;
156	    }
157	
158	    let m = p.start();
159	
160	    p.bump(T!['(']);
161	    if p.at(T![@]) {
162	        parse_at_rule_declarator(p).ok();
